import { app, autoUpdater, BrowserWindow, session, shell } from "electron";
import { InitIPCEvents } from "./IPCEvents";
import { InitEvents } from "./Events";
import path from "path";
import fs from "fs";
import { wait } from "./utilts";
import { EnsurePathExists } from "./Pathes";
// This allows TypeScript to pick up the magic constants that"s auto-generated by Forge"s Webpack
// plugin that tells the Electron app where to look for the Webpack-bundled app code (depending on
// whether you"re running in development or production).
declare const MAIN_WINDOW_WEBPACK_ENTRY: string;
declare const MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY: string;

// app.whenReady().then(() => {
//     autoUpdater.checkForUpdatesAndNotify();
// });


// Handle creating/removing shortcuts on Windows when installing/uninstalling.
if (require("electron-squirrel-startup")) {
    app.quit();
}

const packageJson = JSON.parse(fs.readFileSync(path.join(__dirname, "../../package.json")).toString());

export let win: BrowserWindow;
function createWindow() {
    // Create the browser window.
    win = new BrowserWindow({
        title: `${packageJson.productName} (${packageJson.version})`,
        icon: path.join(__dirname, "../../icons/icon.ico"),

        width: 1400,
        height: 700,
        minHeight: 700,
        minWidth: 1000,

        show: false,
        // opacity: 0,


        movable: true,
        fullscreenable: false,
        webPreferences: {
            nodeIntegration: true,
            contextIsolation: false,
            devTools: !app.isPackaged,
            webSecurity: false,
            preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
        },
        frame: false,
    });

    win.loadURL(MAIN_WINDOW_WEBPACK_ENTRY);
    // .then(async () => {
    // if (!splashWindow.isDestroyed()) splashWindow.close();
    // win.show();

    // let o: number = 0, duration = 200, step = 0.05;

    // let fadeIn = setInterval(() => {
    //     o += step;
    //     if (o >= 1) clearInterval(fadeIn);
    //     else win.setOpacity(o);
    // }, duration * step);
    // });
    win.webContents.once("did-finish-load", () => {
        win.show();
    });

    win.webContents.setWindowOpenHandler(({ url }) => {
        if (url.startsWith("steam://")) {
            shell.openExternal(url);
            return { action: "deny" };
        }
        return { action: "allow" };
    });

    // Open the DevTools.
    if (!app.isPackaged) win.webContents.openDevTools();
}

// This method will be called when Electron has finished
// initialization and is ready to create browser windows.
// Some APIs can only be used after this event occurs.
app.on("ready", () => {
    EnsurePathExists();
    InitIPCEvents();
    InitEvents();
    createWindow();
});

// Quit when all windows are closed, except on macOS. There, it"s common
// for applications and their menu bar to stay active until the user quits
// explicitly with Cmd + Q.
app.on("window-all-closed", () => {
    if (process.platform !== "darwin") {
        app.quit();
    }
});

app.on("activate", () => {
    // On OS X it"s common to re-create a window in the app when the
    // dock icon is clicked and there are no other windows open.
    if (BrowserWindow.getAllWindows().length === 0) {
        createWindow();
    }
});

